mapper.select:
select THIRD_USER_ID, CARD_ID, CARD_TYPE, CHANNEL, THIRD_PAY_ID, REQ_CONTRACT_NO, STATUS, CREATE_TMS, UPDATE_TMS
from APP_USER_PAY_CHANNEL
where THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
  and CARD_TYPE = #{cardType,jdbcType=VARCHAR}
  and CHANNEL = #{channel,jdbcType=VARCHAR}

select THIRD_USER_ID, CARD_ID, CARD_TYPE, CHANNEL, THIRD_PAY_ID, REQ_CONTRACT_NO, STATUS, PAY_ACCOUNT_ID, CREATE_TMS, UPDATE_TMS
from APP_USER_PAY_CHANNEL
where THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
  and CARD_TYPE = #{cardType,jdbcType=VARCHAR}
  and CARD_ID = #{cardId,jdbcType=VARCHAR}
order by CREATE_TMS desc, CHANNEL

select count(1)
from APP_USER_PAY_CHANNEL
where THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}

mapper.update:
update APP_USER_PAY_CHANNEL
set PAY_ACCOUNT_ID = #{payAccountId,jdbcType=VARCHAR},
    UPDATE_TMS = #{updateTms,jdbcType=TIMESTAMP}
where REQ_CONTRACT_NO = #{reqContractNo,jdbcType=VARCHAR}

mapper.delete:
delete from APP_USER_PAY_CHANNEL
where THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
  and CARD_TYPE = #{cardType,jdbcType=VARCHAR}
  and CHANNEL = #{channel,jdbcType=VARCHAR}
